#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-22

# ============================================================================
# scripts/gh-api.mjs — token precedence and import safety (#3653)
# ============================================================================
# The script existed with ZERO call sites and zero tests. Two defects made it
# both unusable and untestable:
#
#   1. token() went straight to `gh auth token` with no env fallback. The whole
#      point of the helper is that `gh` dies in the sandbox, so acquiring the
#      token through `gh` reintroduces the dependency the transport fix removed.
#      The header also claimed that read was "keychain-free", which it is not.
#   2. Importing the module executed the proxy re-exec AND main(), both of which
#      call process.exit(). Any importer was killed on import, so nothing could
#      call it as a library and no unit test could reach token().
#
# These tests make NO network calls. They exercise the token precedence and the
# import contract only.
# ============================================================================

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="${CLAUDE_PROJECT_DIR:-$(cd "$SCRIPT_DIR/../.." && pwd)}"
GH_API="$PROJECT_ROOT/scripts/gh-api.mjs"

PASS=0
FAIL=0

if [[ -t 1 ]]; then
    RED='\033[0;31m'; GREEN='\033[0;32m'; NC='\033[0m'
else
    RED=''; GREEN=''; NC=''
fi

ok()  { PASS=$((PASS + 1)); echo -e "${GREEN}  PASS${NC} $1"; }
bad() { FAIL=$((FAIL + 1)); echo -e "${RED}  FAIL${NC} $1"; }

# A scratch dir with a `gh` that always fails, so the fallback branch is
# deterministic and never touches the real CLI or a credential store.
TMP="$(mktemp -d "${TMPDIR:-/tmp}/gh-api-test.XXXXXX")"
trap 'rm -rf "$TMP"' EXIT
cat > "$TMP/gh" <<'STUB'
#!/usr/bin/env bash
echo "stub gh: refusing on purpose" >&2
exit 1
STUB
chmod +x "$TMP/gh"

# run_node <stdout|stderr> <inline module body> -- runs node with the stub gh on
# PATH. The exit code is CAPTURED, never swallowed: a crash must be
# distinguishable from a legitimately empty result, which is the whole class of
# bug this file exists to test.
run_node() {
    local stream="$1"; shift
    local out rc
    if [[ "$stream" == "stderr" ]]; then
        out="$(cd "$TMP" && PATH="$TMP:$PATH" NODE_USE_ENV_PROXY=1 \
            node --input-type=module -e "$1" 2>&1 >/dev/null)"
        rc=$?
    else
        out="$(cd "$TMP" && PATH="$TMP:$PATH" NODE_USE_ENV_PROXY=1 \
            node --input-type=module -e "$1" 2>/dev/null)"
        rc=$?
    fi
    printf '%s' "$out"
    return "$rc"
}

echo "gh-api.mjs token precedence and import safety"

[[ -f "$GH_API" ]] || { bad "scripts/gh-api.mjs not found"; exit 1; }

# --- 1. GH_TOKEN wins, without shelling out -------------------------------
# `gh` is stubbed to fail, so a value coming back proves the env branch ran.
out="$(GH_TOKEN='tok_from_gh_token' GITHUB_TOKEN='tok_from_github_token' \
    run_node stdout "
      const { token } = await import('file://$GH_API');
      process.stdout.write(token());
    ")"; rc=$?
if [[ "$rc" -eq 0 && "$out" == "tok_from_gh_token" ]]; then
    ok "GH_TOKEN takes precedence and does not shell out to gh"
else
    bad "GH_TOKEN precedence: rc=$rc out='$out' (wanted tok_from_gh_token)"
fi

# --- 2. GITHUB_TOKEN is the second choice ---------------------------------
out="$(GITHUB_TOKEN='tok_from_github_token' run_node stdout "
      const { token } = await import('file://$GH_API');
      process.stdout.write(token());
    ")"; rc=$?
if [[ "$rc" -eq 0 && "$out" == "tok_from_github_token" ]]; then
    ok "GITHUB_TOKEN is used when GH_TOKEN is absent"
else
    bad "GITHUB_TOKEN fallback: rc=$rc out='$out' (wanted tok_from_github_token)"
fi

# --- 3. An empty/whitespace env var must NOT be accepted ------------------
# Otherwise an exported-but-empty GH_TOKEN yields a Bearer of "" and a 401 that
# reads as a permissions problem rather than a missing credential.
out="$(GH_TOKEN='   ' GITHUB_TOKEN='tok_real' run_node stdout "
      const { token } = await import('file://$GH_API');
      process.stdout.write(token());
    ")"; rc=$?
if [[ "$rc" -eq 0 && "$out" == "tok_real" ]]; then
    ok "a whitespace-only GH_TOKEN is skipped, not sent as an empty Bearer"
else
    bad "empty-token guard: rc=$rc out='$out' (wanted tok_real)"
fi

# --- 4. With no env token, the error NAMES the fix ------------------------
# `env -u` cannot invoke a shell function, so unset inside a subshell instead.
err="$(unset GH_TOKEN GITHUB_TOKEN; run_node stderr "
      const { token } = await import('file://$GH_API');
      try { token(); } catch (e) { process.stderr.write(e.message); }
    ")"; rc=$?
if [[ "$rc" -eq 0 && "$err" == *"GH_TOKEN"* && "$err" == *"GITHUB_TOKEN"* ]]; then
    ok "the no-token error names both env vars"
else
    bad "no-token error: rc=$rc should name both vars, got: ${err:0:120}"
fi

# --- 5. Importing must not exit the importing process ---------------------
# This is the defect that made the script un-wireable: BOTH the proxy re-exec
# and main() called process.exit() at import time.
out="$(GH_TOKEN='tok' run_node stdout "
      await import('file://$GH_API');
      process.stdout.write('importer-survived');
    ")"; rc=$?
if [[ "$rc" -eq 0 && "$out" == "importer-survived" ]]; then
    ok "importing the module does not exit the importing process"
else
    bad "import safety: rc=$rc out='$out' (wanted importer-survived)"
fi

# --- 6. The module exports the pieces a caller needs ----------------------
out="$(run_node stdout "
      const m = await import('file://$GH_API');
      process.stdout.write(['token','request','GhApiError'].filter(k => typeof m[k] !== 'undefined').join(','));
    ")"; rc=$?
if [[ "$rc" -eq 0 && "$out" == "token,request,GhApiError" ]]; then
    ok "exports token, request and GhApiError"
else
    bad "exports: rc=$rc out='$out' (wanted token,request,GhApiError)"
fi

# --- 7. The header must not repeat the false keychain-free claim ----------
# grep -q exits 1 on no-match, which is the PASS case here, so the branch is the
# assertion; the exit code is never discarded into a variable.
if grep -q 'keychain-free read' "$GH_API"; then
    bad "header still claims \`gh auth token\` is a keychain-free read"
else
    ok "the false keychain-free claim is gone"
fi

echo ""
echo "  Passed: $PASS"
echo "  Failed: $FAIL"
[[ "$FAIL" -eq 0 ]]
